-- Load encounters for this map
prepareEntitiesList("orcs_fareast_encounters", "mod.class.Encounter", "/data-orcs/general/encounters/fareast.lua")
prepareEntitiesList("orcs_fareast_encounters_npcs", "mod.class.WorldNPC", "/data-orcs/general/encounters/fareast-npcs.lua")
addData{
	wda = { script="orcs+orcs", zones={} },
}
level.data.auto_placelists = { "orcs_fareast_encounters" }

-- Update the Far East name to Var'Eyal (its real name, which the orcs use)
updateZones("zonename", _t"Far East", function(z) z.subtype = _t"Var'Eyal" end)

-- Add a warning before entering atmos territory
onGenerated(function(zone, level, map)
	for _, z in ipairs(level.custom_zones) do
		if z.type == "warning" and z.subtype == "atmos" then
			local warn = require("engine.Entity").new{ on_move = function(self, x, y, who) if who and who.player and not game.zone.atmos_warned and not who:hasQuest("orcs+quarry") then
				if who.runStop then who:runStop(_t"WARNING") end
				game.zone.atmos_warned = true
				require("engine.ui.Dialog"):simplePopup(_t"Danger!", _t"Warning, to the west is #CRIMSON##{bold}#Atmos Tribe#{normal}##LAST# territory. Likely far too dangerous for you!")
			end end}
			for x = z.x1, z.x2 do for y = z.y1, z.y2 do
				game.level.map(x, y, engine.Map.TRIGGER, warn)
			end end
		end
	end
end)

